import AsyncStorage from '@react-native-async-storage/async-storage';
import { Ionicons } from '@expo/vector-icons';
import { Audio } from 'expo-av';
import { router } from 'expo-router';
import React, { useContext, useEffect, useMemo, useRef, useState } from 'react';
import { Animated, Image, ImageBackground, Modal, Platform, Pressable, SafeAreaView, ScrollView, StyleSheet, Text, View } from 'react-native';
import { AuthContext } from '../context/AuthContext';
import expoconfig from '../expoconfig';
import { shuffleOptions } from '../services/shuffleOptions';
import { queueOfflineSubmission, syncOfflineSubmissions } from '../services/offlineSync';
import { recordRelayFirstAttempt, relayCanContinue, relayRunComplete } from '../services/dialogueRelayProgress';
import styles from '../styles/stylesQuackResponseGuided';
import originalAudio from './dialogueRelayAudio';
import conversationAudio from './relayConversationAudio';
import { RELAY_SCENES, RELAY_TOTAL_RESPONSES, RELAY_TRIVIA, RelayChoice, relayExchange } from './dialogueRelayContent';
const dialogueRelayAudio = {...originalAudio,...conversationAudio};

const sprites = {
  SUMI: {
    idle: require('../assets/img/Sumi_PoseB_WinterUni_Smile.png'),
    speaking: require('../assets/img/Sumi_PoseB_WinterUni_Open.png'),
    speakingBlink: require('../assets/img/Sumi_PoseB_WinterUni_EyesClosed_Open.png'),
    blink: require('../assets/img/Sumi_PoseB_WinterUni_EyesClosed_Smile.png'),
    happy: require('../assets/img/Sumi_PoseB_WinterUni_Smile_Blush.png'),
    sad: require('../assets/img/Sumi_PoseB_WinterUni_Frown.png'),
  },
  HARU: {
    idle: require('../assets/img/Sprite Male Dark Hair Neu01.png'),
    speaking: require('../assets/img/Sprite Male Dark Hair Smi02.png'),
    blink: require('../assets/img/Sprite Male Dark Hair Smi01.png'),
    happy: require('../assets/img/Sprite Male Dark Hair Smi01.png'),
    sad: require('../assets/img/Sprite Male Dark Hair Sad01.png'),
  },
};
const MUSIC=require('../assets/audio/sfx/quiz.mp3');
const CORRECT=require('../assets/audio/sfx/correct.mp3');
const WRONG=require('../assets/audio/sfx/incorrect.mp3');
type Phase='tutorial'|'narration'|'sumi'|'haru'|'choice'|'userReply'|'resultFlash'|'reaction'|'feedback'|'finished';
type Answer={sceneId:string;questionIndex:number;choiceId:string;correct:boolean;evaluation:RelayChoice['evaluation'];points:number};
type Save={version:5;sceneIndex:number;questionIndex:number;answers:Answer[];completed?:boolean};

export default function DialogueRelay(){
  const {user}=useContext(AuthContext);
  const [phase,setPhase]=useState<Phase>('tutorial');
  const [sceneIndex,setSceneIndex]=useState(0),[questionIndex,setQuestionIndex]=useState(0);
  const [answers,setAnswers]=useState<Answer[]>([]),[selected,setSelected]=useState<RelayChoice|null>(null);
  const [cultureVisible,setCultureVisible]=useState(false),[guideVisible,setGuideVisible]=useState(false),[exitVisible,setExitVisible]=useState(false);
  const [triviaIndex,setTriviaIndex]=useState(0);
  const [flash,setFlash]=useState<'good'|'bad'|null>(null); const flashOpacity=useRef(new Animated.Value(0)).current,flashScale=useRef(new Animated.Value(.4)).current;
  const [typed,setTyped]=useState(''),[narrationDone,setNarrationDone]=useState(false);
  const [choiceHintVisible,setChoiceHintVisible]=useState(false);
  const [historyVisible,setHistoryVisible]=useState(false);
  const choiceLock=useRef(false);
  const reenacting=useRef(false);
  const [replayRun,setReplayRun]=useState(0);
  const [activeAudioKey,setActiveAudioKey]=useState('');
  const voiceGeneration=useRef(0);
  const [audioError,setAudioError]=useState('');
  const music=useRef<Audio.Sound|null>(null),effect=useRef<Audio.Sound|null>(null),voice=useRef<Audio.Sound|null>(null),correctEffect=useRef<Audio.Sound|null>(null),wrongEffect=useRef<Audio.Sound|null>(null),reactionVoice=useRef<Audio.Sound|null>(null);
  const musicStarting=useRef<Promise<void>|null>(null);
  const effectsStarting=useRef<Promise<void>|null>(null),loadedReactionKey=useRef('');
  const scene=RELAY_SCENES[sceneIndex],current=scene.questions[questionIndex];
  // Remains fixed while listening again, opening hints, or repairing this turn.
  const orderedCurrent=useMemo(()=>({...current,choices:shuffleOptions(current.choices)}),[scene.id,questionIndex]);
  const dialogue=relayExchange(scene.id,questionIndex);
  const correct=answers.filter(a=>a.correct).length,score=answers.reduce((sum,a)=>sum+a.points,0);
  // The order and teaching contract changed. Keep old saves untouched rather
  // than applying their numeric scene indexes to a different conversation.
  const saveKey=`dialogue_relay_v5:${user?.email||'guest'}`;

  const ensureEffects=async()=>{if(correctEffect.current&&wrongEffect.current)return;if(effectsStarting.current)return effectsStarting.current;effectsStarting.current=(async()=>{try{const [good,bad]=await Promise.all([Audio.Sound.createAsync(CORRECT,{shouldPlay:false,volume:.9}),Audio.Sound.createAsync(WRONG,{shouldPlay:false,volume:.9})]);correctEffect.current=good.sound;wrongEffect.current=bad.sound;}catch{}finally{effectsStarting.current=null;}})();return effectsStarting.current;};
  const ensureMusic=async()=>{void ensureEffects();if(music.current){const status=await music.current.getStatusAsync().catch(()=>null);if(status?.isLoaded&&!status.isPlaying)await music.current.playAsync().catch(()=>{});return;}if(musicStarting.current)return musicStarting.current;musicStarting.current=(async()=>{try{await Audio.setAudioModeAsync({playsInSilentModeIOS:true,staysActiveInBackground:false,shouldDuckAndroid:true});const x=await Audio.Sound.createAsync(MUSIC,{shouldPlay:true,isLooping:true,volume:.15});if(music.current)await x.sound.unloadAsync();else music.current=x.sound;}catch{}finally{musicStarting.current=null;}})();return musicStarting.current;};
  const stopVoice=()=>{voiceGeneration.current++;const sound=voice.current;voice.current=null;setActiveAudioKey('');if(sound){sound.setOnPlaybackStatusUpdate(null);void sound.unloadAsync().catch(()=>{});}void music.current?.setVolumeAsync(.15).catch(()=>{});};
  const playVoice=async(key:string,onFinished?:()=>void)=>{
    stopVoice();const generation=voiceGeneration.current;const source=dialogueRelayAudio[key];setAudioError('');
    if(!source){setAudioError('This recording is unavailable. You can read the line and continue.');onFinished?.();return;}
    try{const created=await Audio.Sound.createAsync(source,{shouldPlay:false,volume:1});if(generation!==voiceGeneration.current){await created.sound.unloadAsync();return;}voice.current=created.sound;
      created.sound.setOnPlaybackStatusUpdate(status=>{if(generation!==voiceGeneration.current)return;if(!status.isLoaded&&status.error){stopVoice();setAudioError('The recording stopped unexpectedly. You can replay or use the text.');onFinished?.();return;}if(status.isLoaded&&status.didJustFinish){created.sound.setOnPlaybackStatusUpdate(null);voice.current=null;setActiveAudioKey('');void created.sound.unloadAsync().catch(()=>{});void music.current?.setVolumeAsync(.15).catch(()=>{});onFinished?.();}});
      await music.current?.setVolumeAsync(.035).catch(()=>{});if(generation!==voiceGeneration.current)return;setActiveAudioKey(key);await created.sound.playAsync();
    }catch{if(generation!==voiceGeneration.current)return;stopVoice();setAudioError('Audio could not play. Replay the line or continue using its text.');onFinished?.();}
  };
  // Stop stale speech on navigation; late audio loads cannot speak over a new turn.
  useEffect(()=>()=>stopVoice(),[phase,scene.id,questionIndex,replayRun]);
  const replayConversation=()=>{
    stopVoice();setHistoryVisible(false);setChoiceHintVisible(false);
    reenacting.current=true;choiceLock.current=false;setSelected(null);
    setReplayRun(run=>run+1);setPhase('sumi');
  };
  const nextDialogue=()=>{
    if(phase==='haru')reenacting.current=false;
    setPhase(phase==='sumi'?'haru':'choice');
  };
  useEffect(()=>()=>{for(const ref of [voice,music,effect,correctEffect,wrongEffect])void ref.current?.unloadAsync().catch(()=>{});},[]);
  useEffect(()=>{let live=true;(async()=>{const raw=await AsyncStorage.getItem(saveKey);if(!raw||!live)return;try{const x=JSON.parse(raw);if(x.version!==5||!RELAY_SCENES[x.sceneIndex]?.questions[x.questionIndex]||!Array.isArray(x.answers))return;setSceneIndex(x.sceneIndex);setQuestionIndex(x.questionIndex);setAnswers(x.answers);if(relayRunComplete(x)){setPhase('finished');if(!x.completed){await AsyncStorage.setItem(saveKey,JSON.stringify({version:5,sceneIndex:x.sceneIndex,questionIndex:x.questionIndex,answers:x.answers,completed:true}));if(!x.bonusEarned)void sendScore(x.answers);}}}catch{}})();return()=>{live=false;};},[saveKey]);
  useEffect(()=>{if(phase==='finished'){stopVoice();void music.current?.stopAsync().catch(()=>{});}},[phase]);
  useEffect(()=>{if(phase!=='narration'){setTyped('');return;}let i=0;setTyped('');setNarrationDone(false);const id=setInterval(()=>{i=Math.min(i+2,scene.narration.length);setTyped(scene.narration.slice(0,i));if(i===scene.narration.length){clearInterval(id);setNarrationDone(true);}},22);return()=>clearInterval(id);},[phase,scene.id]);
  useEffect(()=>{if(phase!=='userReply'||!selected)return;let live=true;void playVoice(`choice-${selected.id}`,()=>{if(live)setPhase('resultFlash');});return()=>{live=false;};},[phase,selected?.id]);
  useEffect(()=>{if(phase!=='resultFlash'||!selected)return;let live=true;setFlash(selected.correct?'good':'bad');flashOpacity.setValue(0);flashScale.setValue(.4);Animated.sequence([Animated.timing(flashOpacity,{toValue:1,duration:170,useNativeDriver:true}),Animated.delay(2050),Animated.timing(flashOpacity,{toValue:0,duration:300,useNativeDriver:true})]).start();Animated.spring(flashScale,{toValue:1,friction:5,tension:120,useNativeDriver:true}).start();void playSfx(selected.correct?'correct':'wrong');const timer=setTimeout(()=>{if(!live)return;live=false;void stopFeedbackSfx();setFlash(null);setPhase('reaction');},2600);return()=>{live=false;clearTimeout(timer);};},[phase,selected?.id]);
  useEffect(()=>{
    let live=true;
    if(phase==='sumi'||phase==='haru')void playVoice(`connected-${scene.id}-${questionIndex}-${phase}`,()=>{
      if(!live||!reenacting.current)return;
      if(phase==='haru')reenacting.current=false;
      setPhase(phase==='sumi'?'haru':'choice');
    });
    else if(phase==='reaction'&&selected?.correct)void playVoice(`connected-${scene.id}-${questionIndex}-followup`);
    else if(phase==='reaction'&&!selected?.correct)setPhase('feedback');
    return()=>{live=false;};
  },[phase,scene.id,questionIndex,replayRun]);

  const persist=(over:Partial<Save>={})=>{const state:Save={version:5,sceneIndex,questionIndex,answers,completed:phase==='finished',...over};if(user?.email&&!state.completed)void fetch(`${expoconfig.API_URL}/api/dialogue-relay/progress?email=${encodeURIComponent(user.email)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({answered:state.answers.length,correct:state.answers.filter(a=>a.correct).length})}).catch(()=>{});return AsyncStorage.setItem(saveKey,JSON.stringify(state));};
  const stopFeedbackSfx=async()=>{for(const sound of [correctEffect.current,wrongEffect.current,effect.current]){if(!sound)continue;sound.setOnPlaybackStatusUpdate(null);await sound.stopAsync().catch(()=>{});}await music.current?.setVolumeAsync(.15).catch(()=>{});};
  const playSfx=async(kind:'correct'|'wrong')=>{try{await ensureEffects();let sound=kind==='correct'?correctEffect.current:wrongEffect.current;if(!sound){await effect.current?.unloadAsync().catch(()=>{});const loaded=await Audio.Sound.createAsync(kind==='correct'?CORRECT:WRONG,{shouldPlay:false,volume:.95});effect.current=loaded.sound;sound=loaded.sound;}await music.current?.setVolumeAsync(.025).catch(()=>{});sound.setOnPlaybackStatusUpdate(status=>{if(status.isLoaded&&status.didJustFinish){sound?.setOnPlaybackStatusUpdate(null);void music.current?.setVolumeAsync(.15).catch(()=>{});}});await sound.setPositionAsync(0);await sound.playAsync();}catch{void music.current?.setVolumeAsync(.15).catch(()=>{});}};
  const advance=async(over:Partial<Save>={})=>{if(questionIndex+1<scene.questions.length){setQuestionIndex(questionIndex+1);setPhase('sumi');await persist({questionIndex:questionIndex+1,...over});return;}if(sceneIndex+1<RELAY_SCENES.length){setSceneIndex(sceneIndex+1);setQuestionIndex(0);setPhase('narration');await persist({sceneIndex:sceneIndex+1,questionIndex:0,...over});return;}setPhase('finished');await persist({completed:true});if(user?.email)void fetch(`${expoconfig.API_URL}/api/dialogue-relay/progress?email=${encodeURIComponent(user.email)}`,{method:'DELETE'}).catch(()=>{});void sendScore();};
  const choose=(choice:RelayChoice)=>{if(phase!=='choice'||choiceLock.current)return;choiceLock.current=true;void ensureMusic();const next=recordRelayFirstAttempt<Answer>(answers,{sceneId:scene.id,questionIndex,choiceId:choice.id,correct:choice.correct,evaluation:choice.evaluation,points:choice.points});setAnswers(next);setSelected(choice);setPhase('userReply');void persist({answers:next});};
  const afterFeedback=()=>{const repaired=relayCanContinue(selected);stopVoice();setSelected(null);choiceLock.current=false;if(!repaired){setPhase('choice');return;}void advance();};
  const narrationTap=()=>{void ensureMusic();if(!narrationDone){setTyped(scene.narration);setNarrationDone(true);return;}setTriviaIndex(0);setCultureVisible(true);};
  const closeTrivia=()=>{const notes=RELAY_TRIVIA[scene.id]||[scene.etiquette];if(triviaIndex+1<notes.length){setTriviaIndex(triviaIndex+1);return;}setCultureVisible(false);setTriviaIndex(0);setPhase('sumi');};
  const sendScore=async(savedAnswers:Answer[]=answers)=>{if(!user?.email)return;try{await queueOfflineSubmission(user.email,'/api/scores/high-score',{email:user.email,game:'QUACKRESPONSE_RELAY',mode:'DIALOGUE_RELAY',score:savedAnswers.reduce((sum,a)=>sum+a.points,0),maxScore:RELAY_TOTAL_RESPONSES*3,correctAnswers:savedAnswers.filter(a=>a.correct).length,totalQuestions:RELAY_TOTAL_RESPONSES,completed:true,date:new Date().toISOString()});void syncOfflineSubmissions(user.email);}catch{}};
  const isNarration=phase==='narration',isChoice=phase==='choice',isReaction=phase==='reaction',isDialogue=phase==='sumi'||phase==='haru';

  return <ImageBackground source={scene.background} style={styles.background} imageStyle={styles.backgroundImage} resizeMode="cover">
    <View style={styles.backgroundShade}/><SafeAreaView style={styles.safeArea}>
      <View style={[styles.header,r.gameHeader]}><Pressable style={styles.iconButton} onPress={()=>setExitVisible(true)}><Ionicons name="arrow-back" size={24} color="#351A4A"/></Pressable><View style={[styles.headerCopy,r.centerHeaderCopy]}><Text style={styles.headerEyebrow}>DIALOGUE RELAY · {answers.length}/25</Text><Text style={styles.headerTitle} numberOfLines={1}>{scene.title}</Text></View><Pressable style={styles.iconButton} onPress={()=>setGuideVisible(true)}><Ionicons name="journal-outline" size={23} color="#8423D9"/></Pressable></View>
      <View style={styles.progressTrack}><View style={[styles.progressFill,{width:`${Math.max(2,answers.length/25*100)}%`}]} /></View>
      {!!audioError&&<Text accessibilityRole="alert" style={{color:'#fff',backgroundColor:'#542576',padding:8}}>{audioError}</Text>}
      <View style={styles.storyStage}>
        {(isDialogue||isChoice||isReaction)&&<View style={styles.spriteStage} pointerEvents="none">
          {isChoice?<><SpriteActor who="SUMI" speaking={activeAudioKey.endsWith('-sumi')||activeAudioKey.endsWith('-followup')} position={styles.choiceSpriteLeft}/><SpriteActor who="HARU" speaking={activeAudioKey.endsWith('-haru')} position={styles.choiceSpriteRight}/></>:isReaction?<SpriteActor who="SUMI" speaking={activeAudioKey.endsWith('-followup')} mood="happy" reacting position={r.reactionSpritePosition}/>:<SpriteActor who={phase==='sumi'?'SUMI':'HARU'} speaking={activeAudioKey===`connected-${scene.id}-${questionIndex}-${phase}`} position={phase==='sumi'?styles.soloSpriteRight:styles.soloSpriteLeft}/>}
        </View>}
        {phase==='tutorial'&&<Tutorial start={()=>{void ensureMusic();setPhase('narration');}}/>}
        {isNarration&&<Narration title={`${sceneIndex+1}/10 · ${scene.place}`} text={typed} done={narrationDone} tap={narrationTap}/>} 
        {isDialogue&&<Speech who={phase==='sumi'?'SUMI':'HARU'} text={phase==='sumi'?dialogue.sumi:dialogue.haru} romaji={phase==='sumi'?dialogue.sumiRomaji:dialogue.haruRomaji} replay={replayConversation} next={nextDialogue}/>}
        {(phase==='userReply'||phase==='resultFlash')&&<UserReplyBubble choice={selected}/>} 
        {isReaction&&selected?.correct&&<Speech who="SUMI" text={dialogue.followup} romaji={dialogue.followupRomaji} replay={()=>void playVoice(`connected-${scene.id}-${questionIndex}-followup`)} next={()=>setPhase('feedback')}/>}
        {isChoice&&<RelayChoices current={orderedCurrent} scene={scene} questionIndex={questionIndex} dialogue={dialogue} choose={choose} hint={()=>setChoiceHintVisible(true)} history={()=>setHistoryVisible(true)} replay={replayConversation} preview={(id:string)=>void playVoice(`choice-${id}`)} activeAudioKey={activeAudioKey}/>}
      </View>
      {flash&&<View pointerEvents="none" style={[r.resultOverlay,{backgroundColor:flash==='good'?'rgba(46,158,72,.82)':'rgba(184,52,47,.82)'}]}><View style={r.flashWrap}><Animated.View style={[r.flashBadge,r.flashBadgeLarge,{opacity:flashOpacity,backgroundColor:flash==='good'?'#2E9E48':'#B8342F',transform:[{scale:flashScale}]}]}><Ionicons name={flash==='good'?'checkmark':'close'} size={54} color="#fff"/><Text style={r.flashLabel}>{flash==='good'?'GREAT CHOICE':'LET’S REPAIR IT'}</Text></Animated.View></View></View>}
    </SafeAreaView>
    <ConversationHistory visible={historyVisible} scene={scene} questionIndex={questionIndex} close={()=>setHistoryVisible(false)} replay={(index:number,speaker:string)=>void playVoice(`connected-${scene.id}-${index}-${speaker}`)}/>
    <Culture visible={cultureVisible} text={(RELAY_TRIVIA[scene.id]||[scene.etiquette])[triviaIndex]} index={triviaIndex} total={(RELAY_TRIVIA[scene.id]||[scene.etiquette]).length} close={closeTrivia}/>
    <ChoiceHint visible={choiceHintVisible} text={current.coach} close={()=>setChoiceHintVisible(false)}/>
    <Feedback visible={phase==='feedback'} choice={selected} next={afterFeedback}/>
    <Finish visible={phase==='finished'&&!guideVisible} correct={correct} score={score} review={()=>setGuideVisible(true)} exit={()=>router.replace({pathname:'/QuackResponse',params:{skipLoading:'1'}})}/>
    <Guide visible={guideVisible} answers={answers} score={score} close={()=>setGuideVisible(false)}/>
    <Exit visible={exitVisible} cancel={()=>setExitVisible(false)} leave={async()=>{await persist();router.replace({pathname:'/QuackResponse',params:{skipLoading:'1'}});}}/>
  </ImageBackground>;
}

function RelayChoices({current,scene,questionIndex,dialogue,choose,hint,history,replay,preview,activeAudioKey}:any){
  const [size,setSize]=useState({width:360,height:600});
  const compact=size.width<480||size.height<500;
  const panelWidth=Math.max(0,Math.min(680,size.width-32));
  const centered={width:panelWidth,left:(size.width-panelWidth)/2,right:undefined};
  return <View pointerEvents="box-none" style={StyleSheet.absoluteFillObject} onLayout={e=>setSize(e.nativeEvent.layout)}>
    <View style={[relayUi.dialogue,centered,{maxHeight:size.height*.32}]}>
      <View style={relayUi.toolbar}><View style={relayUi.speakerDot}/><Text style={relayUi.speaker}>Sumi</Text><Text style={relayUi.caption}>Her last line</Text><View style={{flex:1}}/>
        <Pressable accessibilityRole="button" accessibilityLabel="Watch Sumi and Haru repeat this conversation" onPress={replay} style={relayUi.hint}><Ionicons name="refresh-outline" size={17} color="#8423D9"/><Text style={relayUi.hintText}>Repeat</Text></Pressable>
        <Pressable accessibilityRole="button" accessibilityLabel="Open conversation history and Haru's clue" onPress={history} style={relayUi.icon}><Ionicons name="chatbubbles-outline" size={19} color="#8423D9"/></Pressable>
      </View>
      <ScrollView style={{flexShrink:1}}><Text style={[relayUi.japanese,{fontSize:compact?16:19,lineHeight:compact?23:28}]}>{dialogue.sumi}</Text><Text style={relayUi.romaji}>{dialogue.sumiRomaji}</Text></ScrollView>
    </View>
    <View style={[relayUi.choices,centered,{maxHeight:size.height*.49}]}>
      <View style={relayUi.toolbar}><Text style={relayUi.eyebrow}>YOUR REPLY</Text><Text style={relayUi.caption}>{questionIndex+1} of {scene.questions.length}</Text><View style={{flex:1}}/><Pressable accessibilityRole="button" accessibilityLabel="Show a hint for this reply" onPress={hint} style={relayUi.hint}><Ionicons name="bulb-outline" size={16} color="#8423D9"/><Text style={relayUi.hintText}>Hint</Text></Pressable></View>
      <ScrollView style={{flexShrink:1}} contentContainerStyle={{paddingBottom:2}}>
        <Text style={relayUi.task}>{current.prompt}</Text>
        {current.choices.map((c:RelayChoice,i:number)=><Pressable key={c.id} style={({pressed})=>[relayUi.choice,pressed&&relayUi.choicePressed]} onPress={()=>choose(c)}><View style={relayUi.letter}><Text style={relayUi.letterText}>{String.fromCharCode(65+i)}</Text></View><View style={{flex:1,minWidth:0}}><Text style={[relayUi.japanese,{fontSize:compact?15:17,lineHeight:compact?22:25}]}>{c.japanese}</Text><Text style={relayUi.romaji}>{c.romaji}</Text></View><Pressable accessibilityRole="button" accessibilityLabel={`Listen to response ${String.fromCharCode(65+i)}`} style={relayUi.icon} onPress={e=>{e.stopPropagation();preview(c.id);}}><Ionicons name={activeAudioKey===`choice-${c.id}`?'volume-high':'volume-medium-outline'} size={19} color="#8423D9"/></Pressable></Pressable>)}
      </ScrollView>
    </View>
  </View>;
}

// Local styles only: no changes to Reply Coach, sprites, audio, or turn logic.
const relayUi=StyleSheet.create({
  dialogue:{position:'absolute',top:12,left:16,right:16,width:'auto',maxWidth:680,alignSelf:'center',marginHorizontal:'auto',borderRadius:22,backgroundColor:'rgba(255,255,255,.97)',padding:16,borderWidth:1,borderColor:'#EADFF1',shadowColor:'#30133D',shadowOpacity:.12,shadowRadius:14,shadowOffset:{width:0,height:4},elevation:5},
  choices:{position:'absolute',bottom:12,left:16,right:16,maxWidth:680,alignSelf:'center',marginHorizontal:'auto',borderRadius:22,backgroundColor:'rgba(255,255,255,.98)',padding:14,borderWidth:1,borderColor:'#EADFF1',shadowColor:'#30133D',shadowOpacity:.14,shadowRadius:16,shadowOffset:{width:0,height:5},elevation:6},
  toolbar:{flexDirection:'row',alignItems:'center',gap:8,marginBottom:7},speakerDot:{width:7,height:7,borderRadius:4,backgroundColor:'#76B545'},speaker:{fontSize:13,color:'#4A285B',fontWeight:'500'},caption:{fontSize:11,color:'#95849E'},eyebrow:{fontSize:10,letterSpacing:1.2,color:'#79538F',fontWeight:'500'},
  japanese:{color:'#392448',fontWeight:'400'},romaji:{fontSize:11,lineHeight:16,color:'#9275A2',marginTop:3,fontWeight:'400'},task:{fontSize:13,lineHeight:19,color:'#76637E',marginBottom:10},
  icon:{width:36,height:36,alignItems:'center',justifyContent:'center',borderRadius:12},hint:{flexDirection:'row',alignItems:'center',gap:4,paddingHorizontal:9,minHeight:34,borderRadius:11,backgroundColor:'#F6F0FA'},hintText:{fontSize:12,color:'#79538F'},
  choice:{flexDirection:'row',alignItems:'center',gap:10,padding:10,marginBottom:7,borderRadius:15,borderWidth:1,borderColor:'#E9DFF0',backgroundColor:'#fff'},choicePressed:{backgroundColor:'#F7F0FC',borderColor:'#A868DF'},letter:{width:30,height:30,borderRadius:10,backgroundColor:'#F3EAFB',alignItems:'center',justifyContent:'center'},letterText:{fontSize:13,color:'#8423D9',fontWeight:'500'},
});

function ConversationHistory({visible,scene,questionIndex,close,replay}:any){
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={close}><View style={styles.modalBackdrop}><View style={[r.feedback,{maxHeight:'90%'}]}><Text style={r.big}>The conversation so far</Text><Text style={r.body}>{scene.narration}</Text><ScrollView style={{flexShrink:1,width:'100%'}}>{scene.questions.slice(0,questionIndex+1).map((q:any,i:number)=>{const d=relayExchange(scene.id,i);return <View key={i} style={r.answer}>{(['sumi','haru'] as const).map(speaker=><Pressable key={speaker} onPress={()=>replay(i,speaker)}><Text style={r.answerLabel}>{speaker.toUpperCase()} · ↻ REPLAY</Text><Text style={r.answerJp}>{d[speaker]}</Text><Text style={r.answerRomaji}>{d[`${speaker}Romaji`]}</Text></Pressable>)}{i<questionIndex&&<><Text style={r.answerLabel}>YOUR REPAIRED / ACCEPTED REPLY</Text><Text style={r.answerJp}>{q.choices.find((c:RelayChoice)=>c.correct)?.japanese}</Text><Text style={r.answerRomaji}>{q.choices.find((c:RelayChoice)=>c.correct)?.romaji}</Text><Pressable onPress={()=>replay(i,'followup')}><Text style={r.answerLabel}>SUMI · ↻ REPLAY</Text><Text style={r.answerJp}>{d.followup}</Text><Text style={r.answerRomaji}>{d.followupRomaji}</Text></Pressable></>}</View>;})}</ScrollView><Pressable style={styles.primaryButton} onPress={close}><Text style={styles.primaryButtonText}>Back to my reply</Text></Pressable></View></View></Modal>;
}

function SpriteActor({who,position,speaking=false,mood='idle',reacting=false}:{who:'SUMI'|'HARU';position:any;speaking?:boolean;mood?:'idle'|'happy'|'sad';reacting?:boolean}){const mouthOpacity=useRef(new Animated.Value(0)).current,blinkOpacity=useRef(new Animated.Value(0)).current,scale=useRef(new Animated.Value(1)).current;useEffect(()=>{mouthOpacity.setValue(0);blinkOpacity.setValue(0);const mouth=speaking?Animated.loop(Animated.sequence([Animated.timing(mouthOpacity,{toValue:1,duration:75,useNativeDriver:true}),Animated.delay(125),Animated.timing(mouthOpacity,{toValue:0,duration:75,useNativeDriver:true}),Animated.delay(145)])):null;const blink=Animated.loop(Animated.sequence([Animated.delay(speaking?1450:2200),Animated.timing(blinkOpacity,{toValue:1,duration:65,useNativeDriver:true}),Animated.delay(105),Animated.timing(blinkOpacity,{toValue:0,duration:75,useNativeDriver:true}),Animated.delay(speaking?900:700)]));const breathe=Animated.loop(Animated.sequence([Animated.timing(scale,{toValue:1.008,duration:1300,useNativeDriver:true}),Animated.timing(scale,{toValue:1,duration:1300,useNativeDriver:true})]));mouth?.start();blink.start();breathe.start();return()=>{mouth?.stop();blink.stop();breathe.stop();};},[speaking]);useEffect(()=>{if(!reacting)return;scale.setValue(1);Animated.sequence([Animated.timing(scale,{toValue:1.1,duration:130,useNativeDriver:true}),Animated.spring(scale,{toValue:1,friction:4,tension:90,useNativeDriver:true})]).start();},[reacting,mood]);const base=sprites[who][mood];const speakingBlink=who==='SUMI'?sprites.SUMI.speakingBlink:sprites.HARU.blink;return <Animated.View style={[styles.spriteActor,position,{transform:[{scale}]}]}><Image source={base} style={styles.spriteLayer} resizeMode="contain" fadeDuration={0}/>{speaking&&<Animated.Image source={sprites[who].speaking} style={[styles.spriteLayer,{opacity:mouthOpacity}]} resizeMode="contain" fadeDuration={0}/>}<Animated.Image source={speaking?speakingBlink:sprites[who].blink} style={[styles.spriteLayer,{opacity:blinkOpacity}]} resizeMode="contain" fadeDuration={0}/></Animated.View>}
function Tutorial({start}:any){return <View style={r.center}><View style={r.tutorial}><View style={r.tutorialHero}><View style={[r.tutorialIcon,r.tutorialIconHero]}><Ionicons name="chatbubbles" size={28} color="#fff"/></View><View style={{flex:1}}><Text style={r.tutorialKicker}>DIALOGUE RELAY</Text><Text style={r.tutorialTitle}>Follow the conversation,<Text style={r.tutorialTitleAccent}> one reply at a time.</Text></Text></View></View><Text style={r.tutorialIntro}>Step into practical scenes with Sumi and Haru. Listen to the exchange, choose your response, and discover the cultural reason behind it.</Text><View style={r.routeCard}><View style={r.routeLine}/><Step number="01" icon="compass-outline" title="Enter the scene" text="A short narration sets the place and social context."/><Step number="02" icon="people-outline" title="Follow the exchange" text="Listen as Sumi and Haru bring the situation to life."/><Step number="03" icon="chatbubble-ellipses-outline" title="Make your move" text="Take your time. Repair a reply before the conversation continues."/></View><Pressable style={styles.primaryButton} onPress={start}><Text style={styles.primaryButtonText}>Enter the first scene</Text><Ionicons name="arrow-forward" size={18} color="#fff"/></Pressable></View></View>}
function Step({number,icon,title,text}:any){return <View style={r.step}><View style={r.stepMarker}><Text style={r.stepNumber}>{number}</Text><View style={r.stepIcon}><Ionicons name={icon} size={18} color="#8423D9"/></View></View><View style={{flex:1}}><Text style={r.stepTitle}>{title}</Text><Text style={r.stepText}>{text}</Text></View></View>}
function Narration({title,text,done,tap}:any){return <Pressable style={r.narrationWrap} onPress={tap}><View style={r.narrationPage}><View style={r.narrationGlow}/><View style={r.narrationTop}><View style={r.narrationIcon}><Ionicons name="book-outline" size={20} color="#fff"/></View><View style={{flex:1}}><Text style={r.narrationKicker}>SCENE SETTING</Text><View style={r.location}><Ionicons name="location" size={12} color="#7DDA47"/><Text style={r.locationText}>{title}</Text></View></View></View><View style={r.narrationRule}/><Text style={r.narrationText}>{text}</Text><View style={r.narrationFooter}><View style={r.narrationDots}><View style={r.narrationDot}/><View style={[r.narrationDot,{opacity:.55}]}/><View style={[r.narrationDot,{opacity:.25}]}/></View><Text style={r.narrationFooterText}>{done?'Continue to the exchange':'Opening the scene'}</Text><View style={r.narrationNext}><Ionicons name={done?'arrow-forward':'ellipsis-horizontal'} size={15} color="#351A4A"/></View></View></View></Pressable>}
function Speech({who,text,romaji,next,replay}:any){const accent=who==='SUMI'?'#C6478B':'#2F6FA8';return <Pressable style={[r.bubbleWrap,who==='SUMI'?r.bubbleRight:r.bubbleLeft]} onPress={next}><View style={[r.bubble,{borderColor:accent}]}><View style={[r.tail,{borderTopColor:accent},who==='SUMI'?r.tailRight:r.tailLeft]}/><View style={r.speakerRow}><View style={[r.speakerDot,{backgroundColor:accent}]}/><Text style={[r.speaker,{color:accent}]}>{who}</Text><View style={r.speakingTag}><Text style={[r.speakingText,{color:accent}]}>SPEAKING</Text></View></View><Text style={r.jp}>{text}</Text><Text style={r.dialogueRomaji}>{romaji}</Text>{replay&&<Pressable accessibilityLabel="Replay this line" onPress={e=>{e.stopPropagation();replay();}}><Text style={r.listenText}>↻ Replay</Text></Pressable>}<View style={r.tapRow}><Text style={[r.tapText,{color:accent}]}>Tap to continue</Text><Ionicons name="chevron-forward" size={15} color={accent}/></View></View></Pressable>}
function UserReplyBubble({choice}:{choice:RelayChoice|null}){if(!choice)return null;return <View style={r.userReplyStage}><View style={r.userReplyBubble}><View style={r.userReplyHeader}><View style={r.userReplyIcon}><Ionicons name="person" size={16} color="#fff"/></View><Text style={r.userReplyLabel}>YOUR REPLY</Text><View style={r.replyingTag}><Text style={r.replyingTagText}>RESPONDING</Text></View></View><Text style={r.userReplyJapanese}>{choice.japanese}</Text><Text style={r.userReplyRomaji}>{choice.romaji}</Text><View style={r.userReplyPulseRow}><View style={r.userReplyPulse}/><View style={[r.userReplyPulse,{opacity:.65}]}/><View style={[r.userReplyPulse,{opacity:.35}]}/></View></View></View>}
const reactionRomaji=(text?:string)=>text==='いいですね。丁寧で、状況に合っています。'?'Ii desu ne. Teinei de, joukyou ni atte imasu.':text==='分かりました。もう少し詳しく教えてください。'?'Wakarimashita. Mou sukoshi kuwashiku oshiete kudasai.':text==='そうですか。もう一度、確認しましょう。'?'Sou desu ka. Mou ichido, kakunin shimashou.':'Oshii desu. Aite to basho ni au iikata o erabimashou.';
function ChoiceHint({visible,text,close}:any){return <Modal visible={visible} transparent animationType="fade"><View style={styles.modalBackdrop}><View style={r.feedback}><View style={r.hintIcon}><Ionicons name="bulb" size={28} color="#D58A1E"/></View><Text style={r.green}>CONVERSATION CLUE</Text><Text style={r.big}>Notice the social signal</Text><Text style={r.body}>{text}</Text><Pressable style={styles.primaryButton} onPress={close}><Text style={styles.primaryButtonText}>Back to the choices</Text></Pressable></View></View></Modal>}
function Culture({visible,text,index,total,close}:any){return <Modal visible={visible} transparent animationType="fade"><View style={styles.modalBackdrop}><View style={[r.cultureCard,r.cultureCardUpgraded]}><View style={r.cultureAccent}/><View style={r.cultureHeader}><View style={[r.cultureIcon,r.cultureIconUpgraded]}><Ionicons name="flower-outline" size={25} color="#fff"/></View><View style={{flex:1}}><Text style={r.cultureEyebrow}>BEHIND THE MOMENT</Text><Text style={r.cultureTitle}>A note from Sumi</Text></View><View style={r.noteCounter}><Text style={r.noteCounterText}>{index+1}/{total}</Text></View></View><View style={r.cultureQuote}><Ionicons name="information-circle-outline" size={18} color="#65A936"/><Text style={[r.cultureText,r.cultureQuoteText]}>{text}</Text></View><View style={r.cultureTakeaway}><Ionicons name="leaf-outline" size={17} color="#8423D9"/><Text style={r.cultureTakeawayText}>Notice the intention behind the expression—not only the words.</Text></View><Pressable style={styles.primaryButton} onPress={close}><Text style={styles.primaryButtonText}>{index+1<total?'Show the next insight':'Start the conversation'}</Text><Ionicons name="arrow-forward" size={18} color="#fff"/></Pressable></View></View></Modal>}
function Feedback({visible,choice,next}:any){const good=(choice?.points||0)>=2,color=good?'#2E9E48':'#D4453F';return <Modal visible={visible} transparent animationType="fade"><View style={styles.modalBackdrop}><ScrollView style={{maxHeight:"90%",width:"100%",maxWidth:400}}><View style={r.feedback}><View style={[r.ribbon,{backgroundColor:color}]}/><View style={[styles.feedbackIcon,{backgroundColor:`${color}18`}]}><Ionicons name={good?'checkmark-circle':'information-circle'} size={34} color={color}/></View><Text style={[styles.feedbackEyebrow,{color}]}>{choice?.evaluation} · {choice?.points}/3 POINTS</Text><Text style={styles.feedbackReaction}>{choice?.evaluation==='BEST'?'That response fits the moment naturally.':choice?.evaluation==='ACCEPTABLE'?'Polite and understandable, with room to be clearer.':choice?.evaluation==='AWKWARD'?'The meaning may land, but the phrasing creates uncertainty.':'This reply does not complete the task in this exchange.'}</Text><View style={r.answer}><Text style={r.answerLabel}>YOUR RESPONSE</Text><Text style={r.answerJp}>{choice?.japanese}</Text><Text style={r.answerRomaji}>{choice?.romaji}</Text></View><View style={styles.explanationBox}><Text style={styles.explanationLabel}>{good?'WHY THIS WORKS':'WHY THIS NEEDS ADJUSTMENT'}</Text><Text style={styles.explanationText}>{choice?.explanation}</Text></View><View style={r.example}><View style={r.exampleBar}/><View style={{flex:1}}><Text style={r.exampleLabel}>A USEFUL EXAMPLE</Text><Text style={r.exampleJp}>{choice?.example}</Text></View></View><Text style={r.body}>Practice feedback. Your first response stays in the journal; repairing it does not add another scored turn.</Text><Pressable style={styles.primaryButton} onPress={next}><Text style={styles.primaryButtonText}>{choice?.correct?"Continue the conversation":"Repair my reply"}</Text><Ionicons name="arrow-forward" size={18} color="#fff"/></Pressable></View></ScrollView></View></Modal>}
function Finish({visible,correct,score,review,exit}:any){return <Popup visible={visible} icon="checkmark-circle-outline" eyebrow="DIALOGUE RELAY COMPLETE" title="You finished the conversation relay!" text={`All 10 scenes are complete. First-attempt result: ${correct}/${RELAY_TOTAL_RESPONSES} correct · ${score}/${RELAY_TOTAL_RESPONSES*3} points. You can review your responses before leaving.`} primary="Review my responses" action={review} secondary="Return to QuackResponse" secondaryAction={exit}/>}
function Guide({visible,answers,score,close}:any){return <Modal visible={visible} animationType="slide"><SafeAreaView style={styles.reviewPage}><View style={styles.reviewHeader}><Pressable style={styles.iconButton} onPress={close}><Ionicons name="arrow-back" size={23} color="#351A4A"/></Pressable><View><Text style={styles.reviewEyebrow}>DECISION JOURNAL · {score}/75 PTS</Text><Text style={styles.reviewTitle}>Dialogue Relay responses</Text></View></View><ScrollView contentContainerStyle={styles.reviewContent}>{!answers.length?<View style={styles.emptyReview}><Ionicons name="book-outline" size={40} color="#B99EC7"/><Text style={styles.emptyReviewTitle}>Your journal is waiting</Text><Text style={styles.emptyReviewText}>Every completed response will appear here with its explanation.</Text></View>:answers.map((answer:Answer,index:number)=>{const scene=RELAY_SCENES.find(x=>x.id===answer.sceneId);const question=scene?.questions[answer.questionIndex];const choice=question?.choices.find(x=>x.id===answer.choiceId);return <View key={`${answer.sceneId}-${answer.questionIndex}`} style={styles.reviewCard}><View style={styles.reviewCardTop}><Text style={styles.reviewNumber}>RESPONSE {String(index+1).padStart(2,'0')} · {scene?.title}</Text><Text style={[styles.reviewEvaluation,{color:answer.points>=2?'#2E9E48':'#D4453F'}]}>{answer.evaluation} · {answer.points}/3</Text></View><Text style={styles.reviewPrompt}>{question?.prompt}</Text><Text style={styles.reviewSelected}>{choice?.japanese}</Text><Text style={styles.reviewEnglish}>{choice?.romaji}</Text><Text style={styles.reviewExplanation}>{choice?.explanation}</Text></View>})}</ScrollView></SafeAreaView></Modal>} 
function Exit({visible,cancel,leave}:any){return <Popup visible={visible} icon="bookmark" eyebrow="SAVE YOUR PLACE" title="Leave Dialogue Relay?" text="Your exact scene, responses, and current score are saved on this device for this account." primary="Save and return" action={leave} secondary="Keep going" secondaryAction={cancel}/>} 
function Popup({visible,icon,eyebrow,title,text,primary,action,secondary,secondaryAction,children}:any){return <Modal visible={visible} transparent animationType="fade"><View style={styles.modalBackdrop}><View style={styles.exitCard}><Ionicons name={icon} size={39} color="#8423D9"/><Text style={styles.feedbackEyebrow}>{eyebrow}</Text><Text style={styles.exitTitle}>{title}</Text><Text style={styles.exitText}>{text}</Text>{children}<Pressable style={styles.primaryButton} onPress={action}><Text style={styles.primaryButtonText}>{primary}</Text></Pressable>{secondary&&<Pressable style={styles.secondaryButton} onPress={secondaryAction}><Text style={styles.secondaryButtonText}>{secondary}</Text></Pressable>}</View></View></Modal>}

